import{_ as r,D as s,o as t,c as i,m as n,a as c,G as e,S as d}from"./chunks/framework.DuIEtbrD.js";const D=JSON.parse('{"title":"React Native环境配置全指南","description":"新手ReactNative环境配置详细教程","frontmatter":{"title":"React Native环境配置全指南","description":"新手ReactNative环境配置详细教程","keywords":"react,react native,rn,跨端开发,expo,expo router,混合开发","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/react-logo.png"},"headers":[],"relativePath":"frontend/react-native/configure.md","filePath":"frontend/react-native/configure.md","lastUpdated":1776945570000}'),h={name:"frontend/react-native/configure.md"};function m(u,a,b,y,v,g){const o=s("Obsolete"),l=s("Reward"),p=s("Gitalk");return t(),i("div",null,[a[0]||(a[0]=n("h1",{id:"react-native环境配置全指南",tabindex:"-1"},[c("React Native环境配置全指南 "),n("a",{class:"header-anchor",href:"#react-native环境配置全指南","aria-label":'Permalink to "React Native环境配置全指南"'},"​")],-1)),e(o,{date:"2023-12-27"}),a[1]||(a[1]=d(`<p><a href="https://reactnative.dev" target="_blank" rel="noreferrer">React Native</a> 作为 Meta 推出的跨平台移动应用开发框架，允许开发者使用 JavaScript 构建原生级应用。本文将提供一份详尽环境配置指南，覆盖 MacOS 和 Windows 两大操作系统，并针对每个平台分别阐述 iOS 和 Android 的环境搭建方案，同时一些小技巧</p><h2 id="前置准备" tabindex="-1">前置准备 <a class="header-anchor" href="#前置准备" aria-label="Permalink to &quot;前置准备&quot;">​</a></h2><p>这里是 mac、windows 平台都需要的一些环境依赖，开发者可以根据自己系统选择对应的安装操作即可</p><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><p><a href="https://git-scm.com/" target="_blank" rel="noreferrer">git</a>是一个分布式版本控制软件，项目中都会用，就不用多说了。新同学可以查看 git 网址链接学习一下</p><h3 id="node" tabindex="-1">Node <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node&quot;">​</a></h3><p>首先就是操作系统上必须有 NodeJS 环境，且 Node 版本要不小于 18.8，建议使用 LTS 长期稳定版本，一般偶数的为稳定版本</p><p>安装 Node 的方式有很多种，推荐使用包管理器：</p><ul><li>n：推荐 mac 用户使用</li><li>nvm：推荐 windows 用户使用</li></ul><p>具体的安装步骤就不再赘述了，可以查看往期文章<a href="/frontend/node/base.html">Node 手把手安装</a></p><h3 id="包管理器" tabindex="-1">包管理器 <a class="header-anchor" href="#包管理器" aria-label="Permalink to &quot;包管理器&quot;">​</a></h3><p>ReactNative 项目中使用到的一些第三方插件都会从包管理器中拉取，也就是 npm，当我们完成 Node 安装后默认就有了 npm，这里需要提到的是 registry 问题</p><p>由于 npm 的仓库位于国外，对于一些第三方包的安装会有严重的网络问题，为了避免网络造成的一系列问题，可以将仓库代理到国内，代理的方式有很多，最简单的：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> npm set registry xxxx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但这里推荐使用<a href="https://github.com/Pana/nrm" target="_blank" rel="noreferrer">nrm</a>来管理代理</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> npm install -g nrm</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 使用</span></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> nrm ls</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">*</span><span style="color:#BABED8;"> npm ---------- https://registry.npmjs.org/</span></span>
<span class="line"><span style="color:#FFCB6B;">  yarn</span><span style="color:#C3E88D;"> ---------</span><span style="color:#C3E88D;"> https://registry.yarnpkg.com/</span></span>
<span class="line"><span style="color:#FFCB6B;">  tencent</span><span style="color:#C3E88D;"> ------</span><span style="color:#C3E88D;"> https://mirrors.tencent.com/npm/</span></span>
<span class="line"><span style="color:#FFCB6B;">  cnpm</span><span style="color:#C3E88D;"> ---------</span><span style="color:#C3E88D;"> https://r.cnpmjs.org/</span></span>
<span class="line"><span style="color:#FFCB6B;">  taobao</span><span style="color:#C3E88D;"> -------</span><span style="color:#C3E88D;"> https://registry.npmmirror.com/</span></span>
<span class="line"><span style="color:#FFCB6B;">  npmMirror</span><span style="color:#C3E88D;"> ----</span><span style="color:#C3E88D;"> https://skimdb.npmjs.com/registry/</span></span>
<span class="line"><span style="color:#FFCB6B;">  huawei</span><span style="color:#C3E88D;"> -------</span><span style="color:#C3E88D;"> https://repo.huaweicloud.com/repository/npm/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="java-development-kit" tabindex="-1">Java Development Kit <a class="header-anchor" href="#java-development-kit" aria-label="Permalink to &quot;Java Development Kit&quot;">​</a></h3><p>Java JDK 是构建 Android 应用必不可少的依赖，官方是推荐使用<a href="https://www.azul.com/downloads/?package=jdk#zulu" target="_blank" rel="noreferrer">Azul Zulu</a>提供的 JDK</p><p>这里推荐使用 JDK 包管理器<a href="https://github.com/jenv/jenv" target="_blank" rel="noreferrer">jenv</a>，更加方便快捷，支持多平台</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> jenv versions</span></span>
<span class="line"><span style="color:#89DDFF;">*</span><span style="color:#BABED8;"> system </span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">set</span><span style="color:#C3E88D;"> by /Users/user/.jenv/version</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#FFCB6B;">  21.0</span></span>
<span class="line"><span style="color:#FFCB6B;">  21.0.2</span></span>
<span class="line"><span style="color:#FFCB6B;">  openjdk64-21.0.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>使用还是很简单，读者可参考它的文档</p><h2 id="macos-平台配置" tabindex="-1">MacOS 平台配置 <a class="header-anchor" href="#macos-平台配置" aria-label="Permalink to &quot;MacOS 平台配置&quot;">​</a></h2><p>这部分来看看 mac 平台对于 ios、Android 的一些相关配置</p><h3 id="watchman" tabindex="-1">Watchman <a class="header-anchor" href="#watchman" aria-label="Permalink to &quot;Watchman&quot;">​</a></h3><p><a href="https://facebook.github.io/watchman/" target="_blank" rel="noreferrer">Watchman</a>是 Facebook 开发的一个工具，用于监视文件系统中的变化。安装它以获得更好的性能</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> brew install watchman</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> watchman --version</span></span>
<span class="line"><span style="color:#FFCB6B;">2024.01.22.00</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="xcode" tabindex="-1">Xcode <a class="header-anchor" href="#xcode" aria-label="Permalink to &quot;Xcode&quot;">​</a></h3><p>安装<a href="https://developer.apple.com/xcode/" target="_blank" rel="noreferrer">Xcode</a>最简单的方法是通过 Mac App Store。安装 Xcode 也将安装 iOS 模拟器和所有必要的工具来构建你的 iOS 应用</p><h3 id="command-line-tools" tabindex="-1">Command Line Tools <a class="header-anchor" href="#command-line-tools" aria-label="Permalink to &quot;Command Line Tools&quot;">​</a></h3><p>你还需要安装 Xcode 命令行工具。打开 Xcode，然后选择<code>Settings…（或Preferences…）</code>从 Xcode 菜单中。转到位置面板，通过在命令行工具下拉菜单中选择最新版本来安装工具</p><p><u>📢 注意：可能会遇到一些网络问题，可使用魔法</u></p><h3 id="ios-模拟器" tabindex="-1">ios 模拟器 <a class="header-anchor" href="#ios-模拟器" aria-label="Permalink to &quot;ios 模拟器&quot;">​</a></h3><p>然后要安装模拟器，打开<code>Xcode &gt; Settings…（或Preferences…）</code>，然后选择 <code>Platforms（或 Components</code>）选项卡。选择您希望使用的 iOS 对应版本的模拟器</p><p>如果你使用的是 Xcode 14.0 或更高版本来安装模拟器，打开<code>Xcode &gt; Settings &gt; Platforms</code>选项卡，然后点击“+”图标并选择 iOS 选项</p><p><u>📢 注意：可能会遇到一些网络问题，可使用魔法</u></p><h3 id="cocoapods" tabindex="-1">CocoaPods <a class="header-anchor" href="#cocoapods" aria-label="Permalink to &quot;CocoaPods&quot;">​</a></h3><p><a href="https://cocoapods.org/" target="_blank" rel="noreferrer">CocoaPods</a>是 iOS 可用的依赖管理系统之一。#CocoaPods 是一颗 Ruby 宝石。您可以使用最新版本 macOS 附带的 Ruby 版本安装 CocoaPods</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> gem install cocoapods</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> pod --version</span></span>
<span class="line"><span style="color:#FFCB6B;">1.14.3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>到这里在对于 ios 在 mac 的配置就基本上完成了</p><h3 id="android-studio" tabindex="-1">Android Studio <a class="header-anchor" href="#android-studio" aria-label="Permalink to &quot;Android Studio&quot;">​</a></h3><p>如果您是 Android 开发新手，那么设置开发环境可能有些繁琐。如果您已经熟悉 Android 开发，那么您可能需要配置一些东西。在任何一种情况下，请确保仔细遵循下面的几个步骤</p><p>下载 Android Studio 安装<a href="https://developer.android.com/studio" target="_blank" rel="noreferrer">Android Studio</a>过程中，确保选中以下所有项目旁边的框</p><ul><li>Android SDK</li><li>Android SDK Platform</li><li>Android Virtual Device</li></ul><ol><li>安装 Android SDK Android Studio 默认安装最新的 Android SDK。然而，用本地代码构建 React Native 应用需要 <code>Android 15 SDK</code>。额外的 Android SDK 可以通过 Android Studio 中的 SDK 管理器安装</li></ol><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-11_18.44.27.png" alt=""></p><ol start="2"><li>安装 Android SDK CommandLine Tool</li></ol><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-11_18.45.56.png" alt=""></p><ol start="3"><li>安装 Android virtual device 模拟器</li></ol><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-11_18.47.46.png" alt=""></p><p>环境变量 React Native 工具需要设置一些环境变量，以便用本地代码构建应用程序</p><ol start="4"><li>打开<code>.zshrc</code>或<code>.bash_profile</code>等配置以下内容</li></ol><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">export</span><span style="color:#BABED8;"> ANDROID_HOME</span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;">$HOME</span><span style="color:#C3E88D;">/Library/Android/sdk</span></span>
<span class="line"><span style="color:#C792EA;">export</span><span style="color:#BABED8;"> PATH</span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;">$PATH</span><span style="color:#C3E88D;">:</span><span style="color:#BABED8;">$ANDROID_HOME</span><span style="color:#C3E88D;">/emulator</span></span>
<span class="line"><span style="color:#C792EA;">export</span><span style="color:#BABED8;"> PATH</span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;">$PATH</span><span style="color:#C3E88D;">:</span><span style="color:#BABED8;">$ANDROID_HOME</span><span style="color:#C3E88D;">/platform-tools</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>执行source .zshrc后验证 Android 一些环境</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> adb devices  # 应显示设备列表</span></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> emulator -list-avds  # 查看创建的模拟器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>到这里关于 Android 的 Mac 环境就配置好了</p><h2 id="windows-平台配置" tabindex="-1">Windows 平台配置 <a class="header-anchor" href="#windows-平台配置" aria-label="Permalink to &quot;Windows 平台配置&quot;">​</a></h2><p>window 平台不支持 ios 或 mac 平台相关的开发，所以就来看看 Android 的配置</p><p>和 mac 上 Android 的配置一样，首先也是安装 Android Studio，安装及操作步骤可以参考上文 mac 配置的</p><p>不一样的就是环境变量</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/android-windows-variable-configure.png" alt=""></p><p>也是非常简单</p><p>好了，到这里 windows 的配置也就讲完了</p><h2 id="脚手架" tabindex="-1">脚手架 <a class="header-anchor" href="#脚手架" aria-label="Permalink to &quot;脚手架&quot;">​</a></h2><p>在现代 web 开发中越来越多的框架提供脚手架解决方案，使用脚手架可以帮助开发者快速搭建应用，如：ReactCLI、Next、VueCLI、Nuxt 等等，这些框架或者脚手架帮助开发者完成大部分的开发工作，大大提高开发效率</p><p>同样的，为了提升开发效率，React Native 也提供了相关的脚手架或者框架</p><h3 id="expo" tabindex="-1">Expo <a class="header-anchor" href="#expo" aria-label="Permalink to &quot;Expo&quot;">​</a></h3><p><a href="https://docs.expo.dev/" target="_blank" rel="noreferrer">Expo</a>是一个生产级 React Native 框架。Expo 提供了开发人员工具，使开发应用程序变得更加容易，例如基于文件的路由、本地模块的标准库等等</p><p>Expo 是现在官方最推荐的 ReactNative 开发方式，它支持很多功能，开发体验也很好，读者可以认真研究下它的文档</p><p>使用 Expo 快速创建 ReactNative 应用：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> npx create-expo-app@latest</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#指定模板</span></span>
<span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> npx create-expo-app@latest --template</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>选择创建的模板：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-11_17.02.58.png" alt=""></p><h3 id="reactnative-cli" tabindex="-1">ReactNative CLI <a class="header-anchor" href="#reactnative-cli" aria-label="Permalink to &quot;ReactNative CLI&quot;">​</a></h3><p>如果你老早以前就用过 Reactnative 那一定知道他的 CLI，类似与 React Web 脚手架一样，不过目前已经不推荐使用了，expo 在性能和能力方面已经非常出色</p><p>除非你的 APP 特殊场景原因不得不放弃使用 Expo，那么也可以使用<a href="https://reactnative.dev/docs/getting-started-without-a-framework" target="_blank" rel="noreferrer">Community CLI</a></p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">➜</span><span style="color:#C3E88D;"> npx @react-native-community/cli@X.XX.X init AwesomeProject --version X.XX.X</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>好了，到这里关于 ReactNative 的环境配置就讲完了，其实跟着文档一点一点是不会有问题的，一般大多数的问题是关于网络、环境变量。快开始你的 App 开发之旅吧~</p>`,78)),e(l),e(p)])}const B=r(h,[["render",m]]);export{D as __pageData,B as default};
